<?php namespace Database\Seeders; use App\Models\{Category,BahanBaku}; use Illuminate\Database\Seeder; class BahanBakuSeeder extends Seeder {public function run():void{$names=['Beras','Kentang','Mie','Ayam','Telur','Ikan','Daging Sapi','Tahu','Tempe','Kacang Hijau','Wortel','Bayam','Buncis','Kol','Tomat','Pisang','Jeruk','Apel','Garam','Minyak Goreng'];foreach($names as $i=>$n)BahanBaku::firstOrCreate(['kode_bahan'=>'BB-'.str_pad($i+1,3,'0',STR_PAD_LEFT)],['nama_bahan'=>$n,'kategori_id'=>Category::skip($i%6)->first()->id,'satuan'=>'Kg','stok'=>50,'stok_minimum'=>10]);}}
